// В листе Analyzed Jobs одна вакансия встречается несколько раз: разметка
// дописывает строки при каждом прогоне. Перед подсчётом оставляем по одной
// записи на job_id — самую свежую по analysis_date. Без этого метрики
// завышаются кратно числу прогонов.
const byId = new Map();
for (const it of $input.all()) {
  const id = String(it.json.job_id ?? it.json.link ?? '').trim();
  if (!id) continue;
  const prev = byId.get(id);
  if (!prev || String(it.json.analysis_date ?? '') >= String(prev.json.analysis_date ?? '')) {
    byId.set(id, it);
  }
}
const items = [...byId.values()];

// Технические категории. RemoteOK — доска общего профиля, и три четверти
// её вакансий к ИТ отношения не имеют. Навыки по ним считать бессмысленно:
// топ собирался по уборщикам и водителям и показывал «sql (1)».
const TECH = new Set(['Engineering', 'AI', 'Data', 'Support', 'Product']);

let totalJobs = items.length;
let techJobs = 0;
let remoteCount = 0;
const skillsCount = {};
const sourcesCount = {};
const levelsCount = {};
const categoriesCount = {};

for (const item of items) {
  const data = item.json;

  const source = data.source || 'Unknown';
  sourcesCount[source] = (sourcesCount[source] || 0) + 1;

  if (data.is_remote === true || String(data.remote).toLowerCase() === 'true' ||
      String(data.is_remote).toLowerCase().includes('remote')) {
    remoteCount++;
  }

  const category = data.category || 'Other';
  categoriesCount[category] = (categoriesCount[category] || 0) + 1;

  const isTech = TECH.has(category);
  if (isTech) techJobs++;

  // Грейд и навыки считаем только по техническим вакансиям: у остальных
  // «Senior» в заголовке означает senior manager, а не уровень разработчика.
  if (!isTech) continue;

  const level = data.level || data.seniority || 'Not Specified';
  levelsCount[level] = (levelsCount[level] || 0) + 1;

  const rawSkills = data.skills || data.stack || '';
  if (rawSkills) {
    const skillsArray = Array.isArray(rawSkills) ? rawSkills : String(rawSkills).split(',');
    for (const skill of skillsArray) {
      const cleanSkill = String(skill).trim().toLowerCase();
      if (cleanSkill) skillsCount[cleanSkill] = (skillsCount[cleanSkill] || 0) + 1;
    }
  }
}

const topSkills = Object.entries(skillsCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(entry => `${entry[0]} (${entry[1]})`)
  .join(', ');

// Колонки таблицы остаются прежними — новых заголовков в листе Analytics
// заводить не пришлось. Число технических вакансий отдельной ячейки не
// требует: уровни считаются только по ним, поэтому их сумма и есть это число.
const analyticsReport = {
  date: new Date().toISOString().split('T')[0],
  total_jobs: totalJobs,
  remote_jobs: remoteCount,
  sources_breakdown: JSON.stringify(sourcesCount),
  levels_breakdown: JSON.stringify(levelsCount),
  top_skills: topSkills,
};

console.log('всего ' + totalJobs + ', технических ' + techJobs);
return [{ json: analyticsReport }];
